import numpy as np,json
p=np.load('p3.npy')
Kv,Kq,Kd,Kvd,wq,zq,Kw,Kpv,Kpd,wp,zp=[float(x) for x in p]
sub={
 "params":{"Kv":Kv,"Kq":Kq,"Kd":Kd,"Kvd":Kvd,"wq":wq,"zq":zq,"Kw":Kw,"Kpv":Kpv,"Kpd":Kpd,"wp":wp,"zp":zp,"Om":2*np.pi*60,"taud":0.01},
 "defs":{
   "dV":"V-V0",
   "dVs":"Vset-V0",
   "uq":"Kv*dVs-Kq*dV",
   "omega":"(theta-theta0-xth)/(taud*Om)",
   "up":"-Kw*omega-Kpv*dV",
   "Qd":"q1-Kd*dV+Kvd*dVs",
   "Pd":"p1-Kpd*dV"
 },
 "states":{
  "xth":{"rhs":"(theta-theta0-xth)/taud","init":"0"},
  "q1":{"rhs":"q2","init":"0"},
  "q2":{"rhs":"wq**2*(uq-q1)-2*zq*wq*q2","init":"0"},
  "p1":{"rhs":"p2","init":"0"},
  "p2":{"rhs":"wp**2*(up-p1)-2*zp*wp*p2","init":"0"}
 },
 "outputs":{"P":"P0+Pd","Q":"Q0+Qd"}
}
json.dump(sub,open('submission.json','w'),indent=1)
